def shift(message, steps):
    abc = "abcdefghijklmnopqrstuvwxyz"
    moved = abc[steps % 26:] + abc[:steps % 26]
    return message.translate(str.maketrans(abc, moved))

def byte_count(text):
    return len(bytes(text, "utf-8"))

def shift(message, steps):
    return "".join(chr((ord(c) - 97 + steps) % 26 + 97) if c.islower() and c.isascii() else c for c in message)

def byte_count(text):
    return len(text.encode())
